Section Recycle.
Variables (HI t ctx tp key tsd spb ris qs parr : Z).
Hypothesis GEO : art_geo HI t ctx tp tsd spb ris qs.
Hypothesis Htp0 : 0x667fe8 <= tp - 88.
Hypothesis Htsd0 : 0x667fe8 <= tsd.

#[local] Abbreviation INV := (art_rcy_inv HI t ctx tp key tsd spb ris qs parr).

(* [comment removed for export] *)
Definition art_rcy_W (l : list art_qbatch) : list (Z * Z) := [(HI, 2 ^ 64 - HI); (0x142d70 + 152, 40)] ++ map (fun b => (qb_addr b, 8)) l.
(* [comment removed for export] *)
Definition art_rcy_W2 (sp : Z) (l : list art_qbatch) : list (Z * Z) := [(sp - 80, 80); (0x142d70 + 152, 40)] ++ map (fun b => (qb_addr b, 8)) l.
Definition art_qin24 (b : art_qbatch) : Prop := spb + 24 * 2 ^ 32 <= qb_addr b /\ qb_addr b + 8192 <= spb + 24 * 2 ^ 32 + 3758096384.

